import sys

def is_palindrome(s):
    return s == s[::-1]

def solve(s):
    n = len(s)
    for i in range(n + 1):
        new_s = s[:i] + 'a' + s[i:]
        if not is_palindrome(new_s):
            return "YES", new_s
    return "NO", ""

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    t = int(data[0])
    index = 1
    results = []

    for _ in range(t):
        s = data[index]
        result, new_s = solve(s)
        results.append(result)
        if result == "YES":
            results.append(new_s)
        index += 1

    for result in results:
        print(result)

if __name__ == "__main__":
    main()
